export type DeliverabilityBand = 'High' | 'Medium' | 'Low' | 'Burned' | 'Unknown';

export interface EmailAccount {
  id: string;
  smartleadInboxId: string;
  smartleadClientId: string;
  email: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  createdAt: string;
  warmupReputation: number | null;
  deliverabilityBand: DeliverabilityBand;
}

export class EmailAccountEntity {
  id: string;
  smartleadInboxId: string;
  smartleadClientId: string;
  email: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  createdAt: string;
  warmupReputation: number | null;
  deliverabilityBand: DeliverabilityBand;

  constructor(partial: Partial<EmailAccountEntity>) {
    Object.assign(this, partial);
    this.domain = this.deriveDomain(this.email);
    this.deliverabilityBand = this.computeDeliverabilityBand(this.warmupReputation);
  }

  private deriveDomain(email: string): string {
    const parts = email.split('@');
    return parts.length === 2 ? parts[1].toLowerCase() : '';
  }

  private computeDeliverabilityBand(score: number | null): DeliverabilityBand {
    if (score === null || score === undefined) return 'Unknown';
    if (score === 100) return 'High';
    if (score >= 98) return 'Medium';
    if (score >= 95) return 'Low';
    return 'Burned';
  }

  get numberOfCampaignsAssociated(): number {
    return this.campaignIds.length;
  }

  toJSON(): EmailAccount {
    return {
      id: this.id,
      smartleadInboxId: this.smartleadInboxId,
      smartleadClientId: this.smartleadClientId,
      email: this.email,
      domain: this.domain,
      tags: this.tags,
      campaignIds: this.campaignIds,
      createdAt: this.createdAt,
      warmupReputation: this.warmupReputation,
      deliverabilityBand: this.deliverabilityBand,
    };
  }

  static fromJSON(json: EmailAccount): EmailAccountEntity {
    return new EmailAccountEntity(json);
  }
}

