import { IsString, IsArray, IsOptional, IsNumber, ValidateNested, IsEnum } from 'class-validator';
import { Type } from 'class-transformer';
import { DeliverabilityBand } from '../entities/emailAccount.entity';

export class EmailAccountDto {
  @IsString()
  email: string;

  @IsString()
  smartleadClientId: string;

  @IsString()
  @IsOptional()
  smartleadInboxId?: string;

  @IsArray()
  @IsString({ each: true })
  @IsOptional()
  tags?: string[];
}

export class EmailAccountListDto {
  @IsNumber()
  totalNumberOfEmailsToSend: number;

  @IsString()
  smartleadClientId: string;

  @IsString()
  campaignId: string;

  @IsNumber()
  @IsOptional()
  numberOfDaysInCampaign?: number;

  @IsNumber()
  @IsOptional()
  emailsPerInboxPerDay?: number;
}

export class AssociateCampaignDto {
  @IsArray()
  @IsString({ each: true })
  emailAccountIds: string[];

  @IsString()
  campaignId: string;
}

export class EmailAccountResponseDto {
  @IsString()
  id: string;

  @IsString()
  smartleadInboxId: string;

  @IsString()
  smartleadClientId: string;

  @IsString()
  email: string;

  @IsString()
  domain: string;

  @IsArray()
  @IsString({ each: true })
  tags: string[];

  @IsArray()
  @IsString({ each: true })
  campaignIds: string[];

  @IsString()
  createdAt: string;

  @IsNumber()
  @IsOptional()
  warmupReputation: number | null;

  @IsEnum(['High', 'Medium', 'Low', 'Burned', 'Unknown'])
  deliverabilityBand: DeliverabilityBand;

  @IsNumber()
  numberOfCampaignsAssociated: number;
}

export class PaginatedEmailAccountsDto {
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => EmailAccountResponseDto)
  data: EmailAccountResponseDto[];

  @IsNumber()
  total: number;

  @IsNumber()
  page: number;

  @IsNumber()
  pageSize: number;

  @IsNumber()
  totalPages: number;
}

export class DeleteEmailAccountDto {
  @IsString()
  smartleadInboxId: string;
}

export class GetEmailAccountByEmailDto {
  @IsString()
  email: string;
}

export class GetEmailAccountByClientDto {
  @IsString()
  smartleadClientId: string;
}

export class SyncReputationDto {
  @IsArray()
  @IsString({ each: true })
  smartleadInboxIds: string[];
}

export class ImportInboxesDto {
  @IsString()
  smartleadClientId: string;

  @IsArray()
  @IsString({ each: true })
  @IsOptional()
  smartleadInboxIds?: string[];
}

