import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { DatastoreService } from '../datastore/datastore.service';
import { StoreDataDto } from '../datastore/dto/store.dto';
import { FindDataDto } from '../datastore/dto/find.dto';
import { documentType } from '../datastore/entites/documentType';
import { EmailAccountEntity, EmailAccount, DeliverabilityBand } from './entities/emailAccount.entity';
import {
  EmailAccountDto,
  EmailAccountListDto,
  AssociateCampaignDto,
  EmailAccountResponseDto,
  PaginatedEmailAccountsDto,
  DeleteEmailAccountDto,
  GetEmailAccountByEmailDto,
  GetEmailAccountByClientDto,
  SyncReputationDto,
  ImportInboxesDto,
} from './dto/emailAccount.dto';
import { randomUUID } from 'crypto';
import { SmartleadService } from '../smartlead/smartlead.service';

const EMAILS_PER_INBOX_PER_DAY_DEFAULT = 20;
const CAMPAIGN_DAYS_DEFAULT = 10;

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);

  constructor(
    private readonly datastoreService: DatastoreService,
    private readonly smartleadService: SmartleadService,
  ) {}

  async saveEmailAccount(emailAccountDto: EmailAccountDto): Promise<EmailAccountResponseDto> {
    this.logger.log(`Saving email account: ${JSON.stringify(emailAccountDto)}`);

    if (!emailAccountDto.smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }

    const existing = await this.getEmailAccountBySmartleadInboxId(emailAccountDto.smartleadInboxId);
    if (existing) {
      this.logger.log(`Email account already exists, updating: ${emailAccountDto.smartleadInboxId}`);
      return this.updateEmailAccount(existing.id, emailAccountDto);
    }

    const smartleadInbox = await this.fetchSmartleadInboxDetails(
      emailAccountDto.smartleadClientId,
      emailAccountDto.smartleadInboxId,
    );

    if (!smartleadInbox) {
      throw new NotFoundException(`Smartlead inbox not found: ${emailAccountDto.smartleadInboxId}`);
    }

    const entity = new EmailAccountEntity({
      id: randomUUID(),
      smartleadInboxId: emailAccountDto.smartleadInboxId,
      smartleadClientId: emailAccountDto.smartleadClientId,
      email: smartleadInbox.email || emailAccountDto.email,
      tags: emailAccountDto.tags || [],
      campaignIds: [],
      createdAt: smartleadInbox.created_at || new Date().toISOString(),
      warmupReputation: smartleadInbox.warmup_reputation ?? null,
    });

    await this.persistEmailAccount(entity);

    this.logger.log(`Email account saved: ${entity.id}`);
    return entity.toJSON();
  }

  private async updateEmailAccount(id: string, dto: EmailAccountDto): Promise<EmailAccountResponseDto> {
    const existing = await this.getEmailAccountByIdInternal(id);
    if (!existing) {
      throw new NotFoundException(`Email account not found: ${id}`);
    }

    const smartleadInbox = await this.fetchSmartleadInboxDetails(
      existing.smartleadClientId,
      existing.smartleadInboxId,
    );

    const updated = new EmailAccountEntity({
      ...existing,
      email: smartleadInbox?.email || dto.email || existing.email,
      tags: dto.tags ?? existing.tags,
      warmupReputation: smartleadInbox?.warmup_reputation ?? existing.warmupReputation,
    });

    await this.persistEmailAccount(updated);
    return updated.toJSON();
  }

  private async persistEmailAccount(entity: EmailAccountEntity): Promise<void> {
    await this.datastoreService.store(
      new StoreDataDto({
        data: entity.toJSON(),
        context: {
          documentType: documentType.EMAIL_ACCOUNT,
          uniqueId: entity.id,
        },
      }),
    );
  }

  async getEmailAccountById(id: string): Promise<EmailAccountResponseDto | null> {
    const entity = await this.getEmailAccountByIdInternal(id);
    return entity ? entity.toJSON() : null;
  }

  private async getEmailAccountByIdInternal(id: string): Promise<EmailAccountEntity | null> {
    const result = await this.datastoreService.getById(
      new FindDataDto({ id, documentType: documentType.EMAIL_ACCOUNT }),
    );
    if (!result?.data) return null;
    return EmailAccountEntity.fromJSON(result.data);
  }

  async getEmailAccountBySmartleadInboxId(smartleadInboxId: string): Promise<EmailAccountEntity | null> {
    const result = await this.datastoreService.getByField({
      documentType: documentType.EMAIL_ACCOUNT,
      fieldKey: 'data.smartleadInboxId',
      fieldValue: smartleadInboxId,
    });
    if (!result?.data?.length) return null;
    return EmailAccountEntity.fromJSON(result.data[0]);
  }

  async getEmailAccountByEmail(email: string): Promise<EmailAccountResponseDto | null> {
    const result = await this.datastoreService.getByField({
      documentType: documentType.EMAIL_ACCOUNT,
      fieldKey: 'data.email',
      fieldValue: email.toLowerCase(),
    });
    if (!result?.data?.length) return null;
    return EmailAccountEntity.fromJSON(result.data[0]).toJSON();
  }

  async getEmailAccountBySmartleadClientId(clientId: string): Promise<EmailAccountResponseDto[]> {
    const result = await this.datastoreService.getByField({
      documentType: documentType.EMAIL_ACCOUNT,
      fieldKey: 'data.smartleadClientId',
      fieldValue: clientId,
    });
    if (!result?.data?.length) return [];
    return result.data.map((d) => EmailAccountEntity.fromJSON(d).toJSON());
  }

  async getAllEmailAccounts(page = 1, pageSize = 50): Promise<PaginatedEmailAccountsDto> {
    const result = await this.datastoreService.getByField({
      documentType: documentType.EMAIL_ACCOUNT,
      fieldKey: 'data.id',
      fieldValue: { $exists: true },
      pagination: { page, pageSize },
    });

    const data = (result?.data || []).map((d) => EmailAccountEntity.fromJSON(d).toJSON());
    const total = data.length;
    const totalPages = Math.ceil(total / pageSize);

    return {
      data,
      total,
      page,
      pageSize,
      totalPages,
    };
  }

  async deleteEmailAccount(dto: DeleteEmailAccountDto): Promise<{ message: string; id: string }> {
    const entity = await this.getEmailAccountBySmartleadInboxId(dto.smartleadInboxId);
    if (!entity) {
      throw new NotFoundException(`Email account not found: ${dto.smartleadInboxId}`);
    }

    await this.datastoreService.remove({
      id: entity.id,
      documentType: documentType.EMAIL_ACCOUNT,
    });

    this.logger.log(`Email account deleted: ${entity.id}`);
    return { message: 'Email account deleted successfully', id: entity.id };
  }

  async associateEmailAccountsWithCampaign(
    dto: AssociateCampaignDto,
  ): Promise<{ message: string; associatedCount: number }> {
    this.logger.log(`Associating email accounts with campaign: ${dto.campaignId}`);

    const uniqueInboxIds = [...new Set(dto.emailAccountIds)];
    if (uniqueInboxIds.length !== dto.emailAccountIds.length) {
      this.logger.log(`Deduplicated inbox IDs: ${dto.emailAccountIds.length} -> ${uniqueInboxIds.length}`);
    }

    const entities: EmailAccountEntity[] = [];
    for (const inboxId of uniqueInboxIds) {
      const entity = await this.getEmailAccountBySmartleadInboxId(inboxId);
      if (!entity) {
        throw new NotFoundException(`Email account not found: ${inboxId}`);
      }
      entities.push(entity);
    }

    for (const entity of entities) {
      if (!entity.campaignIds.includes(dto.campaignId)) {
        entity.campaignIds.push(dto.campaignId);
        await this.persistEmailAccount(entity);
      }
    }

    this.logger.log(`Associated ${entities.length} email accounts with campaign ${dto.campaignId}`);
    return { message: 'Email accounts associated with campaign successfully', associatedCount: entities.length };
  }

  async getBestEmailAccountsForCampaign(dto: EmailAccountListDto): Promise<EmailAccountResponseDto[]> {
    const {
      smartleadClientId,
      campaignId,
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign = CAMPAIGN_DAYS_DEFAULT,
      emailsPerInboxPerDay = EMAILS_PER_INBOX_PER_DAY_DEFAULT,
    } = dto;

    const requiredPool = Math.floor(
      totalNumberOfEmailsToSend / numberOfDaysInCampaign / emailsPerInboxPerDay,
    );

    this.logger.log(
      `Computing best email accounts for campaign ${campaignId}: ` +
        `totalEmails=${totalNumberOfEmailsToSend}, days=${numberOfDaysInCampaign}, ` +
        `perDay=${emailsPerInboxPerDay}, requiredPool=${requiredPool}`,
    );

    const allAccounts = await this.getEmailAccountBySmartleadClientId(smartleadClientId);
    if (!allAccounts.length) {
      this.logger.warn(`No email accounts found for client ${smartleadClientId}`);
      return [];
    }

    const domainCounts = new Map<string, number>();
    for (const acc of allAccounts) {
      domainCounts.set(acc.domain, (domainCounts.get(acc.domain) || 0) + 1);
    }

    const scored = allAccounts.map((acc) => {
      const sameDomainCount = (domainCounts.get(acc.domain) || 1) - 1;
      return {
        account: acc,
        sameDomainCount,
        createdAt: new Date(acc.createdAt).getTime(),
      };
    });

    scored.sort((a, b) => {
      const bandOrder: Record<DeliverabilityBand, number> = {
        High: 4,
        Medium: 3,
        Low: 2,
        Burned: 1,
        Unknown: 0,
      };

      const bandDiff = bandOrder[b.account.deliverabilityBand] - bandOrder[a.account.deliverabilityBand];
      if (bandDiff !== 0) return bandDiff;

      const campaignDiff = a.account.numberOfCampaignsAssociated - b.account.numberOfCampaignsAssociated;
      if (campaignDiff !== 0) return campaignDiff;

      const domainDiff = a.sameDomainCount - b.sameDomainCount;
      if (domainDiff !== 0) return domainDiff;

      return a.createdAt - b.createdAt;
    });

    const selected = scored.slice(0, requiredPool).map((s) => s.account);
    this.logger.log(`Selected ${selected.length} email accounts for campaign ${campaignId}`);
    return selected;
  }

  async syncReputation(dto: SyncReputationDto): Promise<{ updated: number; errors: string[] }> {
    const errors: string[] = [];
    let updated = 0;

    for (const inboxId of dto.smartleadInboxIds) {
      try {
        const entity = await this.getEmailAccountBySmartleadInboxId(inboxId);
        if (!entity) {
          errors.push(`Inbox not found: ${inboxId}`);
          continue;
        }

        const smartleadInbox = await this.fetchSmartleadInboxDetails(entity.smartleadClientId, inboxId);
        if (!smartleadInbox) {
          errors.push(`Smartlead inbox not found remotely: ${inboxId}`);
          continue;
        }

        entity.warmupReputation = smartleadInbox.warmup_reputation ?? null;
        entity.deliverabilityBand = entity['computeDeliverabilityBand'](entity.warmupReputation);
        await this.persistEmailAccount(entity);
        updated++;
      } catch (e) {
        errors.push(`Failed to sync ${inboxId}: ${e instanceof Error ? e.message : String(e)}`);
      }
    }

    return { updated, errors };
  }

  async importInboxes(dto: ImportInboxesDto): Promise<{ created: number; updated: number; errors: string[] }> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    if (!apiKey) {
      throw new InternalServerErrorException('SMARTLEAD_REPORT_API_KEY not configured');
    }

    let remoteInboxes: any[];
    if (dto.smartleadInboxIds?.length) {
      remoteInboxes = [];
      for (const inboxId of dto.smartleadInboxIds) {
        const res = await fetch(
          `https://server.smartlead.ai/api/v1/email-accounts/${inboxId}?api_key=${apiKey}`,
        );
        if (res.ok) {
          remoteInboxes.push(await res.json());
        }
      }
    } else {
      const res = await fetch(
        `https://server.smartlead.ai/api/v1/email-accounts/?api_key=${apiKey}&client_id=${dto.smartleadClientId}`,
      );
      if (!res.ok) {
        throw new InternalServerErrorException('Failed to fetch email accounts from Smartlead');
      }
      remoteInboxes = await res.json();
    }

    const errors: string[] = [];
    let created = 0;
    let updated = 0;

    for (const inbox of remoteInboxes) {
      try {
        const existing = await this.getEmailAccountBySmartleadInboxId(inbox.id);
        if (existing) {
          existing.email = inbox.email;
          existing.warmupReputation = inbox.warmup_reputation ?? null;
          existing.deliverabilityBand = existing['computeDeliverabilityBand'](existing.warmupReputation);
          existing.createdAt = inbox.created_at || existing.createdAt;
          await this.persistEmailAccount(existing);
          updated++;
        } else {
          const entity = new EmailAccountEntity({
            id: randomUUID(),
            smartleadInboxId: inbox.id,
            smartleadClientId: dto.smartleadClientId,
            email: inbox.email,
            tags: [],
            campaignIds: [],
            createdAt: inbox.created_at || new Date().toISOString(),
            warmupReputation: inbox.warmup_reputation ?? null,
          });
          await this.persistEmailAccount(entity);
          created++;
        }
      } catch (e) {
        errors.push(`Failed to import ${inbox.id}: ${e instanceof Error ? e.message : String(e)}`);
      }
    }

    return { created, updated, errors };
  }

  private async fetchSmartleadInboxDetails(clientId: string, inboxId: string): Promise<any | null> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    if (!apiKey) {
      throw new InternalServerErrorException('SMARTLEAD_REPORT_API_KEY not configured');
    }

    try {
      const res = await fetch(
        `https://server.smartlead.ai/api/v1/email-accounts/${inboxId}?api_key=${apiKey}`,
      );
      if (!res.ok) {
        if (res.status === 404) return null;
        throw new Error(`Smartlead API error: ${res.status}`);
      }
      return await res.json();
    } catch (e) {
      this.logger.error(`Failed to fetch Smartlead inbox ${inboxId}: ${e instanceof Error ? e.message : String(e)}`);
      return null;
    }
  }
}

