@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @Post('accounts')
  @HttpCode(HttpStatus.CREATED)
  async createEmailAccount(@Body() dto: EmailAccountDto): Promise<EmailAccountResponseDto> {
    return this.emailinfraService.saveEmailAccount(dto);
  }

  @Get('accounts/:id')
  async getEmailAccountById(@Param('id') id: string): Promise<EmailAccountResponseDto> {
    const account = await this.emailinfraService.getEmailAccountById(id);
    if (!account) {
      throw new Error('Email account not found');
    }
    return account;
  }

  @Get('accounts/inbox/:smartleadInboxId')
  async getEmailAccountBySmartleadInboxId(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ): Promise<EmailAccountResponseDto> {
    const account = await this.emailinfraService.getEmailAccountBySmartleadInboxId(smartleadInboxId);
    if (!account) {
      throw new Error('Email account not found');
    }
    return account.toJSON();
  }

  @Get('accounts/email/:email')
  async getEmailAccountByEmail(@Param('email') email: string): Promise<EmailAccountResponseDto> {
    const account = await this.emailinfraService.getEmailAccountByEmail(decodeURIComponent(email));
    if (!account) {
      throw new Error('Email account not found');
    }
    return account;
  }

  @Get('accounts/client/:smartleadClientId')
  async getEmailAccountsByClient(
    @Param('smartleadClientId') smartleadClientId: string,
  ): Promise<EmailAccountResponseDto[]> {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(smartleadClientId);
  }

  @Get('accounts')
  async getAllEmailAccounts(
    @Query('page') page = '1',
    @Query('pageSize') pageSize = '50',
  ): Promise<PaginatedEmailAccountsDto> {
    return this.emailinfraService.getAllEmailAccounts(parseInt(page, 10), parseInt(pageSize, 10));
  }

  @Delete('accounts')
  @HttpCode(HttpStatus.OK)
  async deleteEmailAccount(@Body() dto: DeleteEmailAccountDto): Promise<{ message: string; id: string }> {
    return this.emailinfraService.deleteEmailAccount(dto);
  }

  @Post('accounts/associate-campaign')
  @HttpCode(HttpStatus.OK)
  async associateEmailAccountsWithCampaign(
    @Body() dto: AssociateCampaignDto,
  ): Promise<{ message: string; associatedCount: number }> {
    return this.emailinfraService.associateEmailAccountsWithCampaign(dto);
  }

  @Post('accounts/best-for-campaign')
  async getBestEmailAccountsForCampaign(
    @Body() dto: EmailAccountListDto,
  ): Promise<EmailAccountResponseDto[]> {
    return this.emailinfraService.getBestEmailAccountsForCampaign(dto);
  }

  @Post('accounts/sync-reputation')
  async syncReputation(@Body() dto: SyncReputationDto): Promise<{ updated: number; errors: string[] }> {
    return this.emailinfraService.syncReputation(dto);
  }

  @Post('accounts/import')
  async importInboxes(@Body() dto: ImportInboxesDto): Promise<{
    created: number;
    updated: number;
    errors: string[];
  }> {
    return this.emailinfraService.importInboxes(dto);
  }
}

